css:
.split{display:grid;grid-template-columns:30% 1fr;column-gap:40px;align-items:start}
.split__col{position:sticky;top:120px;align-self:start}
.split__rail{display:flex;gap:24px;overflow-x:auto;
  margin-right:calc(50% - 50vw);padding-right:0;scrollbar-width:none}
.split__rail>*{flex:0 0 260px}

/* 上下型：固定面と可動面を上下で割る */
.head{display:flex;justify-content:space-between;align-items:center;padding-inline:48px}
@media(max-width:768px){.split{grid-template-columns:1fr}.split__col{position:static}}
